      case 1u: storm.ApplySlowOp(LightningSlowOp::kTranspose, static_cast<std::uint8_t>(storm_control[9] + storm_mask[10]), static_cast<std::uint8_t>(storm_block[11] ^ storm_mask[12])); break;
